from collections import Counter

def f(g):
    cnt=Counter(x for row in g for x in row)
    bg=cnt.most_common(1)[0][0]
    out_h=int(round(len(g)/3)); out_w=int(round(len(g[0])/3))
    oh,ow=out_h,out_w
    seen=set(); boxes={}
    for r in range(len(g)):
        for c in range(len(g[0])):
            v=g[r][c]
            if v==bg or (r,c) in seen: continue
            st=[(r,c)]; comp=[]
            while st:
                a,b=st.pop()
                if (a,b) in seen or g[a][b]!=v: continue
                seen.add((a,b)); comp.append((a,b))
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    x,y=a+dr,b+dc
                    if 0<=x<len(g) and 0<=y<len(g[0]) and g[x][y]==v and (x,y) not in seen: st.append((x,y))
            rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
            cr=(min(rs)+max(rs))//2; cc=(min(cs)+max(cs))//2
            boxes[v]=(cr//oh*oh, cc//ow*ow)  # cell index in output
    o=[[0]*ow for _ in range(oh)]
    for v,(rr,cc) in boxes.items():
        o[rr][cc]=v
    return o

